import XCTest
@testable import OpenLensKit

/// Decodes REAL adjustment blobs sampled from Daniel's 68k-photo Aperture
/// library (values asserted against the known Python-decoded ground truth).
final class ApertureAdjustmentDecoderTests: XCTestCase {

    private func data(_ hex: String) -> Data {
        var d = Data(); var i = hex.startIndex
        while i < hex.endIndex {
            let j = hex.index(i, offsetBy: 2)
            d.append(UInt8(hex[i..<j], radix: 16)!)
            i = j
        }
        return d
    }

    func testDecodesRealExposureOperation() throws {
        let op = try XCTUnwrap(ApertureAdjustmentDecoder.decode(uuid: "t1", data: data(Self.exposureHex)))
        XCTAssertEqual(op.identifier, "RKExposureOperation")
        XCTAssertEqual(op.displayName, "Exposure")
        XCTAssertTrue(op.enabled)
        XCTAssertEqual(op.parameters["inputEV"] ?? 0, 1.6205673758865249, accuracy: 0.0001)
    }

    func testDecodesRealWhiteBalanceOperation() throws {
        let op = try XCTUnwrap(ApertureAdjustmentDecoder.decode(uuid: "t2", data: data(Self.wbHex)))
        XCTAssertEqual(op.identifier, "RKWhiteBalanceOperation")
        XCTAssertEqual(op.parameters["inputTemperature"] ?? 0, 5283.661412244267, accuracy: 0.01)
        XCTAssertEqual(op.parameters["inputTint"] ?? 0, -14.6688524009962, accuracy: 0.001)
        // NSColor values inside inputKeys must not break decoding.
        XCTAssertTrue(op.enabled)
    }

    func testDecodesRealCropOperation() throws {
        let op = try XCTUnwrap(ApertureAdjustmentDecoder.decode(uuid: "t3", data: data(Self.cropHex)))
        XCTAssertEqual(op.identifier, "RKCropOperation")
        XCTAssertEqual(op.parameters["inputXOrigin"] ?? 0, 952, accuracy: 0.5)
        XCTAssertEqual(op.parameters["inputYOrigin"] ?? 0, 287, accuracy: 0.5)
        XCTAssertEqual(op.parameters["inputWidth"] ?? 0, 2936, accuracy: 0.5)
        XCTAssertEqual(op.parameters["inputHeight"] ?? 0, 1957, accuracy: 0.5)
        // Display parameters hide constrain bookkeeping.
        XCTAssertFalse(op.displayParameters.contains { $0.name.contains("Constrain") })
    }

    func testGarbageDataReturnsNil() {
        XCTAssertNil(ApertureAdjustmentDecoder.decode(uuid: "x", data: Data([0, 1, 2, 3])))
    }

    // MARK: - Real blobs (hex)

    private static let exposureHex = ""
    private static let wbHex = ""
    private static let cropHex = ""
}
